from kivy.app import App
from kivy.uix.gridlayout import GridLayout
from kivy.uix.button import Button
from kivy.uix.behaviors.focus import FocusBehavior
from kivy.uix.behaviors.compoundselection import CompoundSelectionBehavior
from kivy.core.window import Window
from kivy.properties import ListProperty

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    selected_nodes = ListProperty([])

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._typed_number = ""
        self._typed_number_clock = None
        Window.bind(on_key_down=self._on_key_down, on_key_up=self._on_key_up)
        self.selected_nodes = []

    def _on_key_down(self, window, key, scancode, codepoint, modifiers):
        # Handle navigation and selection with keyboard
        if key in (273, 274, 275, 276):  # Up, Down, Right, Left
            self._navigate_with_keys(key)
            return True
        elif 48 <= key <= 57:  # Number keys 0-9
            self._handle_number_typing(chr(key))
            return True
        elif key == 13:  # Enter
            self._select_typed_node()
            return True
        elif key == 27:  # Escape
            self.clear_selection()
            return True
        return False

    def _on_key_up(self, window, key, scancode):
        # Could be used for key up events if needed
        return False

    def _navigate_with_keys(self, key):
        # Find currently focused/selected node
        if self.selected_nodes:
            current = self.selected_nodes[-1]
        else:
            current = 0
        cols = self.cols
        rows = self.rows
        max_index = len(self.children) - 1
        # Kivy's GridLayout children are in reverse order
        current = max_index - current
        if key == 273:  # Up
            next_index = current - cols
        elif key == 274:  # Down
            next_index = current + cols
        elif key == 275:  # Right
            next_index = current + 1
        elif key == 276:  # Left
            next_index = current - 1
        else:
            return
        if 0 <= next_index <= max_index:
            node = max_index - next_index
            self.select_node(node)

    def _handle_number_typing(self, digit):
        from kivy.clock import Clock
        self._typed_number += digit
        if self._typed_number_clock:
            self._typed_number_clock.cancel()
        self._typed_number_clock = Clock.schedule_once(self._reset_typed_number, 1.0)

    def _reset_typed_number(self, *args):
        self._typed_number = ""

    def _select_typed_node(self):
        if self._typed_number:
            try:
                idx = int(self._typed_number) - 1
                if 0 <= idx < len(self.children):
                    node = len(self.children) - 1 - idx
                    self.select_node(node)
            except Exception:
                pass
            self._typed_number = ""

    def select_node(self, node):
        # Deselect all others for single selection
        self.clear_selection()
        super().select_node(node)
        self._update_node_colors()
        self._print_selected_nodes()

    def deselect_node(self, node):
        super().deselect_node(node)
        self._update_node_colors()
        self._print_selected_nodes()

    def clear_selection(self):
        super().clear_selection()
        self._update_node_colors()
        self._print_selected_nodes()

    def _update_node_colors(self):
        for idx, widget in enumerate(reversed(self.children)):
            if idx in self.selected_nodes:
                widget.background_color = (0.2, 0.6, 1, 1)
            else:
                widget.background_color = (1, 1, 1, 1)

    def _print_selected_nodes(self):
        # Print the numbers of selected nodes (1-based)
        selected = [str(len(self.children) - idx) for idx in self.selected_nodes]
        print("Selected nodes:", ", ".join(selected))

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos):
            return super().on_touch_down(touch)
        for idx, widget in enumerate(reversed(self.children)):
            if widget.collide_point(*touch.pos):
                if idx in self.selected_nodes:
                    self.deselect_node(idx)
                else:
                    self.select_node(idx)
                return True
        return super().on_touch_down(touch)

    def on_touch_up(self, touch):
        return super().on_touch_up(touch)

class TestApp(App):
    def build(self):
        grid = SelectableGrid(cols=8, rows=5, spacing=5, padding=5, size_hint=(1, 1))
        for i in range(1, 41):
            btn = Button(text=str(i), background_color=(1, 1, 1, 1))
            btn.bind(on_touch_down=grid.on_touch_down)
            grid.add_widget(btn)
        return grid

if __name__ == '__main__':
    TestApp().run()
